package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.JdbcCollectorHostMemory;import com.lianxibu.site.domain.protocol.*;
import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;
class CollectorHostMemoryNativeTest {
 CollectorHeartbeatsNativeTest f;JdbcCollectorHostMemory store;Instant now=Instant.parse("2026-01-01T00:10:00Z");String epoch="00000000-0000-4000-8000-000000000001";
 DataSource source(){return new CollectorHeartbeatsNativeTest().source();}
 @BeforeEach void setup()throws Exception{f=new CollectorHeartbeatsNativeTest(){@Override DataSource source(){return CollectorHostMemoryNativeTest.this.source();}};f.setup();store=new JdbcCollectorHostMemory(f.db);}
 @AfterEach void cleanup(){if(f!=null&&f.jdbc!=null){f.jdbc.update("DELETE FROM runtime_settings WHERE setting_key=?",JdbcCollectorHostMemory.key(f.node));f.cleanup();}}
 CollectorHostMemoryTelemetry.Parsed body(Instant at,long sequence,long rss){return body(at,sequence,rss,epoch,now.minusSeconds(60),"a".repeat(64),12,"b".repeat(64),0,0);}
 CollectorHostMemoryTelemetry.Parsed body(Instant at,long sequence,long rss,String capture,Instant started,String process,long pid,String cgroup,long oom,long killed){var n=tools.jackson.databind.json.JsonMapper.shared().createObjectNode();n.put("schema_version",CollectorHostMemoryTelemetry.VERSION);n.put("capture_epoch",capture);n.put("capture_started_at",format(started));n.put("process_identity",process);n.put("pid",pid);n.put("sequence",sequence);n.put("observed_at",format(at));n.put("rss_bytes",rss);n.put("cgroup_epoch",cgroup);n.put("maximum_bytes",192L<<20);n.put("oom_events",oom);n.put("oom_kills",killed);return CollectorHostMemoryTelemetry.parse(CanonicalJson.bytes(n));}
 static String format(Instant at){return new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(at);}
 JdbcCollectorHostMemory.Entry save(CollectorHostMemoryTelemetry.Parsed body,Instant received){return f.tx.execute(s->store.save(f.node,1,body,received));}
 @Test void nativeOriginalHistoryIsSeparateFromHeartbeatAndReplaysNeverRefreshEitherTime(){var first=save(body(now,1,10),now);assertEquals(first,save(body(now,1,10),now.plusSeconds(600)));var history=f.tx.execute(s->store.latest(f.node,1));assertEquals(1,history.revision());assertEquals(1,history.samples().size());assertEquals(now,history.latest().receivedAt());assertNull(f.jdbc.queryForObject("SELECT last_seen_at FROM collector_nodes WHERE id=?",java.sql.Timestamp.class,f.node));assertNull(f.tx.execute(s->f.store.latest(f.node,1)));assertFalse(history.toString().contains(f.node));assertFalse(first.toString().contains(epoch));assertThrows(UnsupportedOperationException.class,()->history.samples().clear());}
 @Test void boundedThreeSnapshotsRetainOriginalAckThenRejectEvictedReplay(){var first=save(body(now,1,10),now);save(body(now.plusSeconds(60),2,11),now.plusSeconds(60));save(body(now.plusSeconds(120),3,12),now.plusSeconds(120));assertEquals(first,save(body(now,1,10),now.plusSeconds(180)));save(body(now.plusSeconds(180),4,13),now.plusSeconds(180));var history=f.tx.execute(s->store.latest(f.node,1));assertEquals(3,history.samples().size());assertEquals(4,history.revision());assertEquals(2,history.samples().getFirst().input().sample().sequence());assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now,1,10),now.plusSeconds(240)));}
 @Test void captureIdentitySequenceAndTimeMustMoveConsistently(){save(body(now,1,10),now);assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now,1,11),now));assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now.plusSeconds(60),1,11),now.plusSeconds(60)));assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now,2,11),now));for(var bad:List.of(body(now.plusSeconds(60),2,11,epoch,now.minusSeconds(59),"a".repeat(64),12,"b".repeat(64),0,0),body(now.plusSeconds(60),2,11,epoch,now.minusSeconds(60),"c".repeat(64),12,"b".repeat(64),0,0),body(now.plusSeconds(60),2,11,epoch,now.minusSeconds(60),"a".repeat(64),13,"b".repeat(64),0,0)))assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(bad,now.plusSeconds(60)));assertEquals(1,f.tx.execute(s->store.latest(f.node,1)).revision());}
 @Test void actualNewCaptureNeedsLaterStartAndSameCgroupCountersNeverReset(){save(body(now,1,10,epoch,now.minusSeconds(60),"a".repeat(64),12,"b".repeat(64),3,4),now);String fresh="00000000-0000-4000-8000-000000000002";assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now.plusSeconds(60),1,11,fresh,now,"c".repeat(64),13,"b".repeat(64),3,4),now.plusSeconds(60)));assertThrows(JdbcCollectorHostMemory.Conflict.class,()->save(body(now.plusSeconds(60),1,11,fresh,now.plusSeconds(1),"c".repeat(64),13,"b".repeat(64),2,4),now.plusSeconds(60)));var original=save(body(now.plusSeconds(60),1,11,fresh,now.plusSeconds(1),"c".repeat(64),13,"b".repeat(64),3,4),now.plusSeconds(60));assertEquals(fresh,original.input().sample().captureEpoch());var changed=save(body(now.plusSeconds(120),2,12,fresh,now.plusSeconds(1),"c".repeat(64),13,"d".repeat(64),0,0),now.plusSeconds(120));assertEquals(0,changed.input().sample().oomKills());}
 @Test void nativeUnlimitedAndRssBeyondMaxAreFactsWithoutInventedHealthyQualification(){var n=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(body(now,1,256L<<20).canonical());n.putNull("maximum_bytes");var value=save(CollectorHostMemoryTelemetry.parse(CanonicalJson.bytes(n)),now);assertNull(value.input().sample().maximumBytes());assertEquals(256L<<20,value.input().sample().rssBytes());}
 @Test void nodeRevisionChangeStartsNewHistoryWhileOldAuthorityOrDisabledNodeRollsBack(){save(body(now,1,10),now);f.jdbc.update("UPDATE collector_nodes SET config_revision=2 WHERE id=?",f.node);assertNull(f.tx.execute(s->store.latest(f.node,2)));assertThrows(IllegalStateException.class,()->save(body(now.plusSeconds(60),2,11),now.plusSeconds(60)));var entry=f.tx.execute(s->store.save(f.node,2,body(now.plusSeconds(60),2,11),now.plusSeconds(60)));assertEquals(1,f.tx.execute(s->store.latest(f.node,2)).samples().size());assertEquals(2,f.tx.execute(s->store.latest(f.node,2)).revision());assertEquals(entry,f.tx.execute(s->store.latest(f.node,2)).latest());assertThrows(IllegalStateException.class,()->f.tx.execute(s->store.latest(f.node,1)));f.jdbc.update("UPDATE collector_nodes SET enabled=0 WHERE id=?",f.node);assertThrows(IllegalStateException.class,()->f.tx.execute(s->store.save(f.node,2,body(now.plusSeconds(120),3,12),now.plusSeconds(120))));assertEquals(2,f.tx.execute(s->store.latest(f.node,2)).revision());}
 @Test void corruptedHashClosedFieldsOversizedRowsUpdatedTimeOrUnsafeRevisionCannotBecomeHistory(){save(body(now,1,10),now);String original=f.jdbc.queryForObject("SELECT value_json FROM runtime_settings WHERE setting_key=?",String.class,JdbcCollectorHostMemory.key(f.node));var n=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(original);((tools.jackson.databind.node.ObjectNode)n.get("samples").get(0)).put("payload_hash","0".repeat(64));f.jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?",n.toString(),JdbcCollectorHostMemory.key(f.node));assertThrows(RuntimeException.class,()->f.tx.execute(s->store.latest(f.node,1)));n=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(original);n.put("healthy",true);f.jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?",n.toString(),JdbcCollectorHostMemory.key(f.node));assertThrows(RuntimeException.class,()->f.tx.execute(s->store.latest(f.node,1)));f.jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?","{\"oversized\":\""+"x".repeat(32768)+"\"}",JdbcCollectorHostMemory.key(f.node));assertThrows(RuntimeException.class,()->f.tx.execute(s->store.latest(f.node,1)));f.jdbc.update("UPDATE runtime_settings SET value_json=?,updated_at=? WHERE setting_key=?",original,java.sql.Timestamp.from(now.plusSeconds(1)),JdbcCollectorHostMemory.key(f.node));assertThrows(RuntimeException.class,()->f.tx.execute(s->store.latest(f.node,1)));f.jdbc.update("UPDATE runtime_settings SET updated_at=?,revision=? WHERE setting_key=?",java.sql.Timestamp.from(now),CanonicalJson.MAX_SAFE_INTEGER+1,JdbcCollectorHostMemory.key(f.node));assertThrows(RuntimeException.class,()->f.tx.execute(s->store.latest(f.node,1)));}
 @Test void forgedBodyWrongTransactionFutureAndClockRollbackLeaveNoNewHistory(){assertThrows(IllegalStateException.class,()->store.latest(f.node,1));f.tx.setReadOnly(true);assertThrows(IllegalStateException.class,()->save(body(now,1,10),now));f.tx.setReadOnly(false);var value=body(now,1,10);assertThrows(IllegalStateException.class,()->save(new CollectorHostMemoryTelemetry.Parsed(value.sample(),value.canonical(),"0".repeat(64)),now));assertThrows(IllegalStateException.class,()->save(body(now.plusSeconds(1),1,10),now));assertNull(f.tx.execute(s->store.latest(f.node,1)));save(value,now);assertThrows(IllegalStateException.class,()->save(body(now.plusSeconds(60),2,11),now.minusSeconds(1)));assertEquals(1,f.tx.execute(s->store.latest(f.node,1)).revision());}
 @Test void actualOuterRollbackRemovesWholeNativeSettingWithoutTouchingHeartbeat(){assertThrows(IllegalStateException.class,()->f.tx.execute(s->{store.save(f.node,1,body(now,1,10),now);throw new IllegalStateException("fictional outer rollback");}));assertNull(f.tx.execute(s->store.latest(f.node,1)));assertNull(f.jdbc.queryForObject("SELECT last_seen_at FROM collector_nodes WHERE id=?",java.sql.Timestamp.class,f.node));}
}
